import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import PostCard from '../components/PostCard';

const Profile = () => {
  const { id } = useParams();
  const { user: currentUser, updateUser } = useAuth();
  const navigate = useNavigate();
  const [profileUser, setProfileUser] = useState(null);
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isFollowing, setIsFollowing] = useState(false);
  
  // Edit states
  const [showEditModal, setShowEditModal] = useState(false);
  const [editName, setEditName] = useState('');
  const [editBio, setEditBio] = useState('');
  const [editProfilePic, setEditProfilePic] = useState(null);
  const fileInputRef = useRef(null);
  const [uploading, setUploading] = useState(false);

  const userId = id || currentUser?.id;
  const isOwnProfile = currentUser && userId === currentUser.id;

  useEffect(() => {
    if (!currentUser) {
      navigate('/login');
      return;
    }
    if (!userId) {
      navigate(`/profile/${currentUser.id}`);
      return;
    }
    fetchProfile();
  }, [userId, currentUser]);

  const fetchProfile = async () => {
    setLoading(true);
    try {
      const userRes = await axios.get(`http://localhost:5000/api/users/${userId}`);
      setProfileUser(userRes.data);
      setEditName(userRes.data.name || '');
      setEditBio(userRes.data.bio || '');
      
      const postsRes = await axios.get(`http://localhost:5000/api/posts/user/${userId}`);
      setPosts(postsRes.data);
      
      if (currentUser) {
        setIsFollowing(userRes.data.followers?.includes(currentUser.id));
      }
    } catch (err) {
      console.error('Error fetching profile:', err);
      if (err.response?.status === 404) {
        navigate('/');
      }
    }
    setLoading(false);
  };

  // FOLLOW/UNFOLLOW
  const handleFollow = async () => {
    if (!currentUser) return;
    try {
      const res = await axios.put(`http://localhost:5000/api/users/follow/${userId}`);
      setIsFollowing(!isFollowing);
      const updatedUser = { ...currentUser };
      if (isFollowing) {
        updatedUser.following = updatedUser.following?.filter(uid => uid !== userId) || [];
      } else {
        updatedUser.following = [...(updatedUser.following || []), userId];
      }
      updateUser(updatedUser);
      setProfileUser(prev => ({
        ...prev,
        followers: isFollowing 
          ? prev.followers?.filter(uid => uid !== currentUser.id) || []
          : [...(prev.followers || []), currentUser.id]
      }));
    } catch (err) {
      console.error('Error following user:', err);
    }
  };

  // UPDATE PROFILE PICTURE
  const handleProfilePictureUpdate = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setUploading(true);
    const formData = new FormData();
    formData.append('profilePicture', file);

    try {
      const res = await axios.put('http://localhost:5000/api/users/profile-picture', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      
      updateUser(res.data);
      setProfileUser(prev => ({ ...prev, profilePicture: res.data.profilePicture }));
      alert('✅ Profile picture updated successfully!');
    } catch (err) {
      console.error('Error uploading profile picture:', err);
      alert('❌ Failed to upload profile picture. Please try again.');
    }
    setUploading(false);
  };

  // UPDATE PROFILE (Name + Bio)
  const handleProfileUpdate = async () => {
    try {
      const res = await axios.put('http://localhost:5000/api/users/profile', {
        name: editName,
        bio: editBio
      });
      
      updateUser(res.data);
      setProfileUser(prev => ({ ...prev, name: res.data.name, bio: res.data.bio }));
      setShowEditModal(false);
      alert('✅ Profile updated successfully!');
    } catch (err) {
      console.error('Error updating profile:', err);
      alert('❌ Failed to update profile. Please try again.');
    }
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading profile...</p>
      </div>
    );
  }

  if (!profileUser) {
    return (
      <div className="error-container">
        <h2>👤 User Not Found</h2>
        <button onClick={() => navigate('/')}>Go to Feed</button>
      </div>
    );
  }

  return (
    <div className="profile-container">
      {/* ===== COVER PHOTO ===== */}
      <div className="profile-cover">
        <div className="cover-image"></div>
        {/* Edit Cover Photo - Facebook Style */}
        {isOwnProfile && (
          <button className="edit-cover-btn">
            📷 Edit Cover Photo
          </button>
        )}
      </div>

      {/* ===== PROFILE INFO ===== */}
      <div className="profile-info-section">
        <div className="profile-avatar-section">
          <div className="profile-avatar-wrapper">
            <img 
              src={profileUser.profilePicture || '/default-avatar.png'} 
              alt={profileUser.username}
              className="profile-avatar"
            />
            {/* Change Profile Picture - Facebook Style */}
            {isOwnProfile && (
              <>
                <button 
                  className="change-avatar-btn"
                  onClick={() => fileInputRef.current.click()}
                  disabled={uploading}
                >
                  {uploading ? '⏳' : '📷'}
                </button>
                <input
                  type="file"
                  ref={fileInputRef}
                  onChange={handleProfilePictureUpdate}
                  accept="image/*"
                  style={{ display: 'none' }}
                />
              </>
            )}
          </div>
          
          <div className="profile-name-section">
            <h1>{profileUser.name || profileUser.username}</h1>
            <p className="username-text">@{profileUser.username}</p>
            {isOwnProfile && (
              <span className="profile-badge">👤 You</span>
            )}
          </div>
        </div>

        {/* ===== STATS ===== */}
        <div className="profile-stats">
          <div className="stat-item">
            <span className="stat-number">{profileUser.followers?.length || 0}</span>
            <span className="stat-label">Followers</span>
          </div>
          <div className="stat-item">
            <span className="stat-number">{profileUser.following?.length || 0}</span>
            <span className="stat-label">Following</span>
          </div>
          <div className="stat-item">
            <span className="stat-number">{posts.length}</span>
            <span className="stat-label">Posts</span>
          </div>
        </div>

        {/* ===== ACTION BUTTONS - Facebook Style ===== */}
        <div className="profile-actions">
          {isOwnProfile ? (
            // OWN PROFILE: Edit Profile Button (Facebook Style)
            <>
              <button 
                className="edit-profile-btn" 
                onClick={() => {
                  setEditName(profileUser.name || '');
                  setEditBio(profileUser.bio || '');
                  setShowEditModal(true);
                }}
              >
                ✏️ Edit Profile
              </button>
              <button className="more-btn">⋯</button>
            </>
          ) : (
            // OTHER'S PROFILE: Follow + Message Buttons (Facebook Style)
            <>
              <button 
                className={`follow-btn ${isFollowing ? 'following' : ''}`} 
                onClick={handleFollow}
              >
                {isFollowing ? '✓ Following' : '+ Follow'}
              </button>
              <button className="message-btn">💬 Message</button>
            </>
          )}
        </div>
      </div>

      {/* ===== BIO SECTION ===== */}
      <div className="profile-bio-section">
        <div className="bio-display">
          {profileUser.bio ? (
            <p className="profile-bio">{profileUser.bio}</p>
          ) : (
            <p className="profile-bio-empty">
              {isOwnProfile ? '✏️ Click "Edit Profile" to add your bio' : 'No bio yet'}
            </p>
          )}
        </div>
      </div>

      {/* ===== POSTS ===== */}
      <div className="profile-posts-section">
        <h2>📝 Posts</h2>
        {posts.length === 0 ? (
          <div className="no-posts">
            <p>{isOwnProfile ? 'You haven\'t posted anything yet' : 'No posts yet'}</p>
            {isOwnProfile && (
              <button onClick={() => navigate('/')}>📝 Create a Post</button>
            )}
          </div>
        ) : (
          posts.map(post => (
            <PostCard 
              key={post._id} 
              post={post} 
              onUpdate={fetchProfile}
              onDelete={fetchProfile}
            />
          ))
        )}
      </div>

      {/* ===== EDIT PROFILE MODAL - Facebook Style ===== */}
      {showEditModal && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Edit Profile</h2>
              <button className="modal-close" onClick={() => setShowEditModal(false)}>✕</button>
            </div>
            
            <div className="modal-body">
              {/* Profile Picture Preview */}
              <div className="edit-avatar-section">
                <img 
                  src={profileUser.profilePicture || '/default-avatar.png'} 
                  alt="Profile" 
                  className="edit-avatar"
                />
                <button 
                  className="edit-avatar-btn"
                  onClick={() => fileInputRef.current.click()}
                >
                  📷 Change Photo
                </button>
              </div>

              {/* Name Input */}
              <div className="edit-field">
                <label>Name</label>
                <input
                  type="text"
                  value={editName}
                  onChange={(e) => setEditName(e.target.value)}
                  placeholder="Your full name"
                  className="edit-input"
                />
              </div>

              {/* Bio Input */}
              <div className="edit-field">
                <label>Bio</label>
                <textarea
                  value={editBio}
                  onChange={(e) => setEditBio(e.target.value)}
                  placeholder="Tell us about yourself..."
                  maxLength={200}
                  className="edit-textarea"
                />
                <span className="char-count">{editBio.length}/200</span>
              </div>
            </div>

            <div className="modal-footer">
              <button className="cancel-btn" onClick={() => setShowEditModal(false)}>
                Cancel
              </button>
              <button className="save-btn" onClick={handleProfileUpdate}>
                💾 Save Changes
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Profile;
